mapper.select:
SELECT id AS image_id, memory_id, object_key
FROM memory_image
WHERE memory_id IS NULL
  AND created_at < #{createdBefore}
ORDER BY id
LIMIT #{limit}

SELECT id AS image_id, memory_id, object_key
FROM memory_image
WHERE member_id = #{memberId}
  AND memory_id IS NULL
ORDER BY id
LIMIT #{limit}

mapper.delete:
DELETE FROM memory_image
WHERE id = #{imageId}
  AND memory_id IS NULL
